def merge(intervals):
    if not intervals:
        return []
    intervals = sorted(intervals, key=lambda iv: iv[0])   # sort by start
    merged = [intervals[0][:]]
    for start, end in intervals[1:]:
        last = merged[-1]
        if start <= last[1]:              # overlaps the current block
            last[1] = max(last[1], end)   # extend, never shrink
        else:
            merged.append([start, end])   # gap: start a new block
    return merged

def greedy_coins(coins, amount):
    count = 0
    for c in sorted(coins, reverse=True):
        count += amount // c
        amount %= c
    return count if amount == 0 else -1

def dp_coins(coins, amount):
    INF = float("inf")
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        dp[a] = min((dp[a - c] + 1 for c in coins if c <= a), default=INF)
    return dp[amount] if dp[amount] != INF else -1

coins = [1, 3, 4]
for amount in range(1, 100):
    if greedy_coins(coins, amount) != dp_coins(coins, amount):
        print("greedy fails at", amount)   # 6
        break

